package iq.yasserapps.studio;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;
public class WindowInventoryTest{
 @Test public void streamingAndCancel()throws Exception{File f=File.createTempFile("inventory",".apk");try{try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){z.putNextEntry(new ZipEntry("assets/cross.txt"));byte[] p=new byte[32765];Arrays.fill(p,(byte)'x');z.write(p);z.write("telegram".getBytes(StandardCharsets.UTF_8));z.closeEntry();z.putNextEntry(new ZipEntry("res/layout/sample.xml"));z.write("update available".getBytes(StandardCharsets.UTF_16LE));z.closeEntry();z.putNextEntry(new ZipEntry("assets/large.bin"));byte[] b=new byte[65536];for(int i=0;i<520;i++)z.write(b);z.closeEntry();}List<Integer> progress=new ArrayList<>();WindowInventory.Result r=WindowInventory.scan(f,(a,b,c)->progress.add(a),()->false);assertEquals(3,r.total);assertEquals(2,r.matched);assertEquals(2,r.scanned);assertEquals(1,r.skipped);assertTrue(r.partial);assertEquals(Integer.valueOf(3),progress.get(progress.size()-1));WindowInventory.Result c=WindowInventory.scan(f,(a,b,d)->{},()->true);assertTrue(c.partial);assertEquals(0,c.scanned);}finally{f.delete();}}
}